# Generate the final prediction
rows = 7
cols = 13
bg = 3
fg = 0

output = [[bg] * cols for _ in range(rows)]
center_r = 3

for r in range(max(0, center_r-1), min(rows, center_r+2)):
    rel_r = r - center_r

    # Pattern based on absolute distance from center
    if abs(rel_r) % 2 == 0:
        # Even distance: center-like pattern
        for c in range(cols):
            if c % 2 == 0:
                output[r][c] = fg
            else:
                output[r][c] = bg
    else:
        # Odd distance: inverted pattern
        for c in range(cols):
            if c % 2 == 1:
                output[r][c] = fg
            else:
                output[r][c] = bg

print("Final prediction:")
for row in output:
    print(' '.join(str(x) for x in row))
